function hexRgb(h){return parseInt(h.slice(1,3),16)+','+parseInt(h.slice(3,5),16)+','+parseInt(h.slice(5,7),16)}
function setAccent(hex){
  currentColor=hex;
  var r=document.documentElement;
  r.style.setProperty('--acc',hex);
  r.style.setProperty('--acc-rgb',hexRgb(hex));
}

function statLevel(v){
  if(v<100)return{en:'Sideshow',color:'#7A6448'};
  if(v<300)return{en:'Understudy',color:'#9A8060'};
  if(v<500)return{en:'Featured Act',color:'#B09040'};
  if(v<700)return{en:'Headliner',color:'#B8862E'};
  if(v<850)return{en:'Star of the Show',color:'#A24868'};
  if(v<980)return{en:'Legend',color:'#5A3E8A'};
  if(v<1000)return{en:'Otherworldly',color:'#7A1220'};
  return{en:'Beyond the Veil',color:'#FFD700'};
}

function renderGauges(){
  var wrap=g('gauge-row');if(!wrap)return;
  var h='';
  STATS.forEach(function(s){
    var v=statVals[s.id]!=null?statVals[s.id]:200;
    statVals[s.id]=v;
    var lv=statLevel(v);
    var pct=v/10;
    h+='<div class="gauge-col">'+
      '<div class="gauge-tier" id="gtier-'+s.id+'" style="color:'+lv.color+'">'+lv.en+'</div>'+
      '<div class="tube" style="position:relative">'+
        '<div class="tube-fill" id="tfill-'+s.id+'" style="height:'+pct+'%;background:linear-gradient(180deg,'+lv.color+',rgba('+hexRgb(lv.color)+',.5))"></div>'+
        '<input type="range" class="gauge-slider" min="0" max="1000" value="'+v+'" id="stat-'+s.id+'">'+
      '</div>'+
      '<div class="tube-bulb"><div class="tube-bulb-fill" id="tbulb-'+s.id+'" style="background:'+lv.color+'"></div></div>'+
      '<div class="gauge-nm">'+s.nm+'</div>'+
    '</div>';
  });
  wrap.innerHTML=h;
  STATS.forEach(function(s){
    var inp=g('stat-'+s.id);
    if(inp)inp.addEventListener('input',function(){updateStat(s.id,parseInt(this.value))});
  });
}
function updateStat(id,v){
  statVals[id]=v;
  var lv=statLevel(v);
  var t=g('gtier-'+id);if(t){t.textContent=lv.en;t.style.color=lv.color}
  var f=g('tfill-'+id);if(f){f.style.height=(v/10)+'%';f.style.background='linear-gradient(180deg,'+lv.color+',rgba('+hexRgb(lv.color)+',.5))'}
  var b=g('tbulb-'+id);if(b)b.style.background=lv.color;
}

