    nation:gv('f-nation')==='Custom'?gv('f-nationCustom'):gv('f-nation'),
    nationCustom:gv('f-nationCustom'),region:gv('f-region'),family:gv('f-family'),background:gv('f-background'),
    role:gv('f-role'),stats:{}
  };
  STATS.forEach(function(s){out.stats[s.id]=statVals[s.id]});
  if(curSpecies==='human'){
    out.occupation=gv('f-occupation');out.ahkonStance=gv('f-ahkonStance');out.govTies=gv('f-govTies');
  }else{
    out.thirdEye=gv('f-thirdEye');out.govStatus=gv('f-govStatus');
    out.magicSpecialty=gv('f-magicSpecialty');out.aspettHistory=gv('f-aspettHistory');
  }
  if(out.role==='Circus Performer')out.performerSpecialty=gv('f-performerSpecialty');
  out.traits=selTraits.slice();
  out.acts=acts.filter(function(a){return a.name||a.desc});
  out.personality=gv('f-personality');out.goal=gv('f-goal');out.bond=gv('f-bond');
  out.fear=gv('f-fear');out.philosophy=gv('f-philosophy');out.secret=gv('f-secret');out.quote=gv('f-quote');
  out.scenario=curScenario;out.scenarioCustom=gv('f-scenarioCustom');
  var json=JSON.stringify(out,null,2);
  var ov=g('ink-overlay');
  if(ov)ov.classList.add('on');
  setTimeout(function(){
    if(ov)ov.classList.remove('on');
    sendToST(json);
  },1700);
});
